function main(): void {
  const deps: Record<string, string[]> = { a: ["b"], b: [] };
  const seen = new Set<string>();
  const order: string[] = [];
  const visit = (n: string) => {
    if (seen.has(n)) return;
    seen.add(n);
    for (const d of deps[n] ?? []) visit(d);
    order.push(n);
  };
  Object.keys(deps).forEach(visit);
  console.log(order);
  const hist = ["a", "b", "a"];
  const counts = hist.reduce((a, s) => { a[s] = (a[s] ?? 0) + 1; return a; }, {} as Record<string, number>);
  console.log(counts);
}
